import { Pipe, PipeTransform } from "@angular/core";

@Pipe({
  name: "customDate",
})
export class CustomDatePipe implements PipeTransform {
  // Add your code here
  transform(value: any): string {
    let date: Date;

    if (value instanceof Date) {
      date = value; // Directly use if already a Date object
    } else {
      date = new Date(value); // Try converting string or other input to a Date object
    }

    // Ensure the value is a valid date
    if (isNaN(date.getTime())) {
      console.error("Invalid date passed to CustomDatePipe:", value);
      return "Invalid Date"; // Handle invalid date gracefully
    }

    // Format the date to "DD.MM.YYYY"
    let day = date.getDate();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();

    let formattedDay = day.toString().padStart(2, "0");
    let formattedMonth = month.toString().padStart(2, "0");

    return `${formattedDay}.${formattedMonth}.${year}`;
  }
}
